import os,re
def imports(m):
    p=m.replace('.','/')+'.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M) if os.path.exists(p) else []
def clos(seed):
    seen,st=set(),[seed]
    while st:
        m=st.pop()
        if m not in seen: seen.add(m); st+=imports(m)
    return seen
red={'AlgebraicJacobian.Cohomology.CechTwistedCoherenceReduction','AlgebraicJacobian.Albanese.SymPowInvariantsAwayEquiv'}
for seed in ['AlgebraicJacobian','AlgebraicJacobian.Jacobian','AlgebraicJacobian.AbelJacobi']:
    c=clos(seed)
    print(seed, len(c), 'red inside:', sorted(red&c))
# who imports the red ones
allm=[]
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): allm.append(os.path.join(root,f)[:-5].replace('/','.'))
allm.append('AlgebraicJacobian')
for r in red:
    print('importers of',r,':',[m for m in allm if r in imports(m)])
